        'perm.settings:write.description': 'Modificar las opciones y la configuración del sitio. Puede cambiar cómo se comporta tu sitio.',
        'perm.users:read.label': 'Leer usuarios',
        'perm.users:read.description': 'Ver una vista limitada de las cuentas de usuario (sin contraseñas ni secretos).',
        'perm.email:admin.label': 'Administrar el correo',
        'perm.email:admin.description': 'Configurar y administrar el correo y el servidor de correo.',
        'perm.email:provider.label': 'Enviar correo como proveedor (nivel administrador)',
        'perm.email:provider.description': 'Actuar como el proveedor de correo saliente del sitio: envía, y puede leer, cada mensaje que el sitio manda a través de él. Si además le dejas llevar el correo de restablecimiento de contraseña y de verificación (Ajustes → Correo de la cuenta), recibe esos enlaces y puede apoderarse de cualquier cuenta, también de las de administración: trata este permiso como hacer administrador al plugin.',
        'perm.smtp:inbound.label': 'Recibir correo de internet (puerto 25)',
        'perm.smtp:inbound.description': 'WordJS abre el puerto SMTP 25 para este plugin y le entrega todo el correo que llega de internet. Solo un plugin puede tener este permiso a la vez: quítaselo primero al que lo tenga.',
        'perm.notifications:send.label': 'Enviar notificaciones',
        'perm.notifications:send.description': 'Enviar notificaciones dentro del panel a los administradores.',
        'perm.notifications:provider.label': 'Proveedor de notificaciones (nivel administrador)',
        'perm.notifications:provider.description': 'Actuar como el sistema que entrega las notificaciones del sitio. Recibe el contenido completo, sin ocultar nada, de cada notificación que entrega —incluidos los códigos y enlaces de acceso que envían otros plugins—, así que trata este permiso como hacer administrador al plugin.',
        'perm.express:register_route.label': 'Registrar rutas de la API',
        'perm.express:register_route.description': 'Añadir sus propios endpoints HTTP bajo la API. Se ejecutan en el entorno aislado del plugin.',
        'perm.admin_menu:register.label': 'Añadir al menú de administración',
        'perm.admin_menu:register.description': 'Añadir sus propios elementos a la barra lateral de administración.',
        'perm.assets:write.label': 'Añadir scripts y estilos a las páginas públicas',
        'perm.assets:write.description': 'Cargar un archivo JavaScript o CSS de su propio directorio en tus páginas públicas. El script se ejecuta en el navegador de cada visitante, con acceso a todo lo que ve o escribe en la página. WordJS comprueba que el archivo está dentro del directorio del plugin y escribe la etiqueta él mismo (el plugin no puede inyectar HTML), pero el código al que apunta es del plugin.',
        'perm.browser:script.label': 'Ejecutar código en tu navegador',
        'perm.browser:script.description': 'Ejecuta código en tu navegador con tu sesión de administrador. Su página de administración, sus extensiones y sus bloques del editor se cargan dentro de este mismo panel, así que ese código puede hacer todo lo que tú puedes hacer aquí: crear usuarios, cambiar roles, instalar plugins. No está aislado ni analizado. Concédelo solo si confías en este plugin tanto como en una cuenta de administrador.',
        'plugins.notGranted.title': 'La interfaz de este plugin no está cargada',
        'plugins.notGranted.body': 'La interfaz de este plugin no se sirve hasta que concedas «Ejecutar código en tu navegador» ({permission}) en Plugins → Permisos.',
        'plugins.notGranted.trust': 'Ese permiso ejecuta el código del plugin en este panel con la sesión de quien lo abra. Concédelo solo si confías en {plugin} tanto como en una cuenta de administrador. Solo un administrador puede concederlo.',
        'plugins.notGranted.open': 'Abrir los permisos de {plugin}',
        'plugins.notGranted.unavailable.title': 'Esta pantalla no está disponible',
        'plugins.notGranted.unavailable.body': 'Un administrador todavía no ha habilitado la interfaz de este plugin. Pide a un administrador que la habilite.',
        'perm.roles:declare.label': 'Registrar sus propios roles de usuario',
        'perm.roles:declare.description': 'Añade los roles de usuario que se listan abajo, para que puedas dar a alguien acceso a las pantallas de este plugin y a nada más. Un rol así solo puede tener los permisos propios de este plugin, además de entrar al panel de administración y a la página de su propia cuenta: la plataforma rechaza cualquier otra cosa, así que nunca puede llegar a tu contenido, tus usuarios, tus ajustes ni a otro plugin. Tú eliges quién lo tiene, en Usuarios; si algunos usuarios ya lo tienen, junto al rol se indica cuántos.',
        'perm.posts:read.label': 'Leer todas las publicaciones',
        'perm.posts:read.description': 'Recibir cada publicación y página cuando se crea, actualiza o borra, incluidos los borradores y el contenido privado y programado (nunca las contraseñas de las publicaciones).',
        'perm.comments:read.label': 'Leer comentarios',
        'perm.comments:read.description': 'Recibir cada comentario cuando se envía o se borra, incluidos los no aprobados, y vetar comentarios antes de que se guarden (antispam). El correo, la dirección IP y el navegador de quien comenta se retienen.',
        'perm.comments:pii.label': 'Ver los datos personales de quienes comentan',
        'perm.comments:pii.description': 'Recibir además el correo, la dirección IP y el agente de usuario del navegador de cada persona que comenta, con los eventos de comentarios. Lo necesitan los servicios antispam; son datos personales de tus visitantes.',
        'perm.notifications:read.label': 'Leer notificaciones',
        'perm.notifications:read.description': 'Recibir una copia de cada notificación del panel enviada a cualquier usuario. Los códigos de restablecimiento, los tokens y los enlaces de verificación se ocultan.',
        'perm.media:private_read.label': 'Entregar archivos multimedia privados',
        'perm.media:private_read.description': 'Leer la descripción de los archivos PRIVADOS de la biblioteca de medios y enviar su contenido como respuesta de las rutas propias del plugin. El plugin decide quién recibe un archivo privado (por ejemplo, un comprador con un enlace de descarga pagado), así que concédelo solo a un plugin en el que confíes para mantener privados esos archivos.',
        'perm.network.label': 'Red saliente',
        'perm.network.description': 'Hacer llamadas de red salientes (fetch / sockets). Es un riesgo de exfiltración: los datos pueden salir de tu servidor. Concédelo solo si confías en este plugin.',
        'plugins.marketplace.grantNote.install': 'Instalar no concede nada. Al activar el plugin, el diálogo de activación muestra estos permisos y se los concede al confirmar; después puedes retirar cualquiera en Permisos.',
        'plugins.marketplace.grantNote.update': 'Actualizar no cambia lo concedido: los permisos que el plugin ya tiene se mantienen, y los nuevos de esta versión quedan sin conceder hasta que los concedas en Permisos.',
