        'motion.intro.title': '¿Qué es un movimiento y para qué sirve?',
        'motion.intro.body': 'Un movimiento es una animación con nombre — por ejemplo «aparece subiendo al entrar en pantalla». En el editor enlazas bloques a él y todos se mueven igual. Si lo cambias aquí, cambian a la vez todas las páginas que lo usan, sin editar ninguna.',
